Only classes 0-7 appear. I look for each skill's rule by comparing logit tables with candidate rules and spectra, using recent logit change from history as well because it is more skill-specific than the shared a-bias.
```python
def silu(x): return x/(1+np.exp(-x))
A,B=np.meshgrid(np.arange(32),np.arange(32),indexing="ij")
def fwd(P):
    out=[]
    for s in range(4):
        X=np.zeros((1024,68)); X[np.arange(1024),A.ravel()]=1; X[np.arange(1024),32+B.ravel()]=1; X[:,64+s]=1
        h=silu(X@P["l1.weight"].T+P["l1.bias"]); h=silu(h@P["l2.weight"].T+P["l2.bias"]); out.append(h@P["l3.weight"].T+P["l3.bias"])
    return np.array(out)
def hist(st):
    d=np.load("history/step_%05d.npz"%st); return {n:d[n] for n in NAMES}
import os
print(sorted(os.listdir("history"))[-3:], list(np.load("history/step_00300.npz").keys())[:6])
L=fwd(hist(300))[:,:,:8]; L0=fwd(hist(200))[:,:,:8]; D=L-L0
np.save("L300.npy",L)
a=A.ravel(); b=B.ravel()
C={}
for m in [2,3,4,5,6,7,8,16,32]:
    C[f"(a+b)%{m}"]=(a+b)%m; C[f"(a-b)%{m}"]=(a-b)%m; C[f"(a*b)%{m}"]=(a*b)%m; C[f"a%{m}"]=a%m; C[f"b%{m}"]=b%m
for k in [2,3,4,5]:
    for j in [2,3,4,5]:
        C[f"a%{k}+b%{j}"]=a%k+b%j; C[f"(a%{k})*(b%{j})"]=(a%k)*(b%j)
C["xor"]=(a^b); C["and"]=a&b; C["or"]=a|b; C["min"]=np.minimum(a,b); C["max"]=np.maximum(a,b); C["|a-b|"]=abs(a-b); C["a>b"]=(a>b)*1
C["pc(a)"]=np.array([bin(x).count("1") for x in a]); C["pc(b)"]=np.array([bin(x).count("1") for x in b]); C["pc(xor)"]=np.array([bin(x).count("1") for x in a^b])
C["pc(a)+pc(b)"]=C["pc(a)"]+C["pc(b)"]
for k,v in list(C.items()):
    C[k+"&7"]=v%8
for name,T in [("logits",L),("delta200-300",D)]:
  for s in range(4):
    p=T[s].argmax(1); res=[]
    for k,v in C.items():
        # mutual information between candidate value and predicted class
        vals=np.unique(v)
        if len(vals)>64: continue
        H=np.zeros((vals.max()+1,8)); np.add.at(H,(v,p),1)
        P=H/H.sum(); px=P.sum(1,keepdims=True); py=P.sum(0,keepdims=True)
        mi=np.nansum(np.where(P>0,P*np.log(P/(px*py+1e-12)+1e-12),0))
        res.append((round(float(mi),3),k,len(vals)))
    res.sort(reverse=True); print(name,"skill",s,res[:8])
for s in range(4):
    Z=L[s]-L[s].mean(1,keepdims=True); pw=np.zeros((32,32))
    for c in range(8):
        t=Z[:,c].reshape(32,32); t=t-t.mean(); pw+=np.abs(np.fft.fft2(t))**2
    i=np.argsort(-pw.ravel())[:10]; print("fft skill",s,[(int(x//32),int(x%32),int(pw.ravel()[x])) for x in i], "total",int(pw.sum()))
